n effort * stock_kg * HARVEST_PRODUCTIVITY\n39\t\n40\t\n41\tdef apply_regrowth(stock_kg):\n42\t    \"\"\"Logistic growth on the leftover (post-harvest) stock — matches\n43\t    Gupta et al.'s CPRModel.step():\n44\t    ΔR = growth_rate * R * (1 - R/capacity), applied to what's left after\n45\t    harvest, not a flat per-round add. Growth slows as the stock nears\n46\t    carrying capacity and (unlike a flat add) can't outrun a depleted lake.\"\"\"\n47\t    grown = stock_kg + GROWTH_RATE * stock_kg * (1 - stock_kg / CARRYING_CAPACITY_KG)\n48\t    return min(grown, CARRYING_CAPACITY_KG)\n49\t\n50\t\n51\tdef apply_consumption(payoff, harvested_kg):\n52\t    \"\"\"Running per-agent balance: this trip's catch in, the fixed\n53\t    consumption cost out — matches Gupta et al.'s CPRAgent.harvest():\n54\t    self.payoff += harvest_amount; self.payoff -= self.model.consumption.\n55\t    Unlike catch/regrowth this isn't about the lake at all — it's whether\n56\t    a fisher can keep feeding themselves from what they bring in.\"\"\"\n57\t    return payoff + harvested_kg - CONSUMPTION_KG\n58\t\n59\t\n60\tdef is_dead(payoff):\n61\t    \"\"\"Matches Gupta et al.'s `if self.payoff < 0: self.dead = True` —\n62\t    permanent once true; nothing in this project ever resurrects an agent.\"\"\"\n63\t    return payoff < 0\n64\t\n65\t\n66\tdef alive_agent_ids(agents, runtime):\n67\t    \"\"\"The agent_id iteration order every action should use, not\n68\t    state[\"agents\"] directly — excludes anyone in runtime[\"dead_agents\"].\n69\t    One shared helper so death exclusion can't be forgotten by an action\n70\t    rewrite the way a hand-rolled check per action could be.\"\"\"\n71\t    dead = set(runtime.get(\"dead_agents\", []))\n72\t    return [agent_id for agent_id in agents if agent_id not in dead]\n73\t\n74\t\n75\tdef available_stock(runtime):\n76\t    return runtime[\"stock_kg\"]\n```\n\n**`actions/rules/harvest/trip_cap.py`** — TripCapRule(class), after_agent(method)\n\n```python\n