ndent of any one action ---\n42\t\n43\t    def before_round(self, state, round_number):\n44\t        \"\"\"Once per round, before ANY action in this round's schedule has\n45\t        run. `state` is the full round-state dict (no single ActionContext\n46\t        exists yet at this point — nothing has been resolved to one\n47\t        action's participants).\"\"\"\n48\t        return None\n49\t\n50\t    def after_round(self, state, round_number):\n51\t        \"\"\"Once per round, after EVERY action in this round's schedule has\n52\t        already run.\"\"\"\n53\t        return None\n54\t\n55\t    # --- action-level: fires once per round for this rule's own action ---\n56\t\n57\t    def before_action(self, ctx):\n58\t        \"\"\"Once, before this action's own participants are processed this\n59\t        round. `ctx` is the action's ActionContext.\"\"\"\n60\t        return None\n61\t\n62\t    def after_action(self, ctx, round_record):\n63\t        \"\"\"Once, after this action's round_record has been fully built —\n64\t        may mutate `round_record` and/or `ctx.state` directly (a stock\n65\t        override, a tally adjustment, a community-wide consequence). This\n66\t        is where a \"the whole action's outcome\" rule belongs, as opposed\n67\t        to a per-agent one.\"\"\"\n68\t        return None\n69\t\n70\t    # --- per-agent: only meaningful for an action whose handler calls\n71\t    # these explicitly inside its own per-agent loop (every handler in\n72\t    # this project does, including the generic Level-2 path) ---\n73\t\n74\t    def is_eligible(self, ctx, agent_id):\n75\t        \"\"\"False skips this agent's LLM call entirely this round (a live\n76\t        ban). Called at most once per agent per round.\"\"\"\n77\t        return True\n78\t\n79\t    def describe(self, ctx, agent_id):\n80\t        \"\"\"One already-in-world-phrased sentence describing whatever this\n81\t        rule currently has to say to this agent, or None. Every active\n82\t        rule's non-None output is joined into one constraints line.\"\"\"\n83\t        return None\n84\t\n85\t    def after_agent(self, ctx, agent_id, record_entry):\n86\t        \"\"\"Once per participating agent, right after their own\n87\t        record_entry dict has been built from their response — return a\n88\t        dict of fields to merge onto it (e.g. {\"harvested_kg\": 12.0,\n89\t        \"note\": \"trimmed to the 15kg limit\"}), or None for no change.\n90\t        Multiple rules run in state[\"config\"][\"rules\"][action] order, each\n91\t        seeing the previous rule's already-applied patch on\n92\t        `record_entry` — this is the ordering-dependent chain (a reserve\n93\t        rule seeing a cap rule's already-trimmed number) the old\n94\t        raw_kg/proposed_kg threading provided; a rule needing the\n95\t        pre-any-rule original value re-derives it from a field no rule\n96\t        touches (harvest's own \"effort\" field, say), the same technique\n97\t        `engine.llm_agents._harvest_shortfall_clause()` already uses.\"\"\"\n98\t        return None\n99\t\n100\t    def on_agent_settled(self, ctx, agent_id, record_entry):\n101\t        \"\"\"Once per agent, after EVERY rule's after_agent() has already\n102\t        applied its patch — `record_entry` here is the fully-settled\n103\t        final state, not the intermediate view after_agent() sees mid-chain.\n104\t        For a side effect that must react to the final outcome rather than\n105\t        any one rule's own contribution to it (starting a ban countdown\n106\t        because the settled record turned out to be a violation, say).\n107\t        Return value is ignored — this hook is for side effects\n108\t        (ctx.rule_state(self.key), ctx.objects, ctx.events), never for\n109\t        further patching record_entry itself; use after_agent() for that.\"\"\"\n110\t        return None\n111\t\n112\t\n113\t@dataclass\n```\n\n\n> Some file sections were trimmed for size. For a specific